import subprocess
import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("Interval and duration must be positive")
    system = platform.system()
    if system == "Windows":
        command = ['wmic', 'cpu', 'get', 'loadpercentage']
    else:
        command = ['top', '-bn1']
    records = []
    end_time = time.time() + duration
    while time.time() < end_time:
        output = subprocess.check_output(command, shell=False).decode('utf-8')
        if system == "Windows":
            lines = output.strip().split('\n')
            if len(lines) > 1:
                cpu_usage = lines[1].strip()
            else:
                cpu_usage = "0"
        else:
            lines = output.split('\n')
            for line in lines:
                if '%Cpu(s)' in line:
                    parts = line.split(',')
                    idle = float(parts[3].split()[0].replace('%id', ''))
                    cpu_usage = str(100.0 - idle)
                    break
            else:
                cpu_usage = "0"
        record = {'timestamp': time.time(), 'cpu_usage': cpu_usage}
        records.append(record)
        time.sleep(interval)
    try:
        with open(LOGFILE_PATH, 'w') as f:
            json.dump(records, f)
    except IOError:
        return None
    return LOGFILE_PATH

