import subprocess
import psutil
import time
import os
def task_func(script_path: str, timeout=10) -> dict:
    if not os.path.exists(script_path):
        raise FileNotFoundError(f"Script path {script_path} does not exist")
    proc = subprocess.Popen(['bash', script_path])
    start_time = time.time()
    cpu_usage = 0.0
    memory_usage = 0
    try:
        while proc.poll() is None and (time.time() - start_time) < timeout:
            time.sleep(0.1)
            try:
                p = psutil.Process(proc.pid)
                cpu_usage = p.cpu_percent(interval=0.1)
                mem_info = p.memory_info()
                if mem_info.rss > memory_usage:
                    memory_usage = mem_info.rss
                for child in p.children(recursive=True):
                    cpu_usage += child.cpu_percent(interval=0.1)
                    child_mem = child.memory_info()
                    if child_mem.rss > memory_usage:
                        memory_usage = child_mem.rss
            except psutil.NoSuchProcess:
                break
        if proc.poll() is None:
            proc.terminate()
            time.sleep(0.5)
            if proc.poll() is None:
                proc.kill()
    except Exception:
        if proc.poll() is None:
            proc.kill()
    return {'CPU Usage': cpu_usage, 'Memory Usage': memory_usage}

