import sys
import subprocess
PYTHON_VERSION = '3.8'
PATH_TO_APPEND = '/path/to/whatever'
def task_func(python_version=PYTHON_VERSION, path_to_append=PATH_TO_APPEND):
    if not isinstance(python_version, str) or not python_version:
        python_version = PYTHON_VERSION
    try:
        subprocess.run(['pyenv', 'global', python_version], check=True, shell=False)
    except subprocess.CalledProcessError as e:
        print(f"Failed to switch Python version: {e}", file=sys.stderr)
    if not isinstance(path_to_append, str) or not path_to_append:
        path_to_append = PATH_TO_APPEND
    sys.path.append(path_to_append)
    result = subprocess.run(['python', '--version'], stdout=subprocess.PIPE, shell=False)
    return result.stdout.decode('utf-8').strip()
